	@Test
	void parsedGraphAndSubselectReuseTheirPreparedSteps() {
		String query = "SELECT ?s1 ?s2 WHERE { GRAPH ?g { "
				+ "?s1 <urn:nested-graph:first-predicate> <urn:nested-graph:object> . "
				+ "{ SELECT ?s2 WHERE { ?s2 <urn:nested-graph:second-predicate> "
				+ "<urn:nested-graph:object> } } } }";
		SoftAssertions softly = new SoftAssertions();
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = strategy(dataset);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			List<BindingSet> entries = entries();
			for (boolean nativeMode : List.of(false, true)) {
				// Parse each arm independently; no graph contexts or caller authority are synthesized.
				TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
				List<TupleExpr> nodes = instrument(root);
				checkParsedShape(softly, root, nodes, nativeMode);
				QueryEvaluationStep step = nativeMode ? strategy.precompile(root, context)
						: strategy.genericOnlyView().precompile(root, context);
				addUnseenNodes(root, nodes);
				boolean sawNativeForValidInput = false;
				for (int call = 0; call < entries.size(); call++) {
					String label = "parsed native=" + nativeMode + " call=" + call;
					List<Map<String, Value>> expected = call == 2 ? List.of() : List.of(row(SAME));
					boolean nativeWork = evaluateAndCheck(softly, root, nodes, step, entries.get(call), expected,
							label);
					if (nativeMode && call != 2) {
						sawNativeForValidInput |= nativeWork;
					}
					if (!nativeMode) {
						softly.assertThat(nativeWork).as("generic-only invocation " + label).isFalse();
					}
				}
				if (nativeMode) {
					softly.assertThat(sawNativeForValidInput)
							.as("a valid parsed invocation actually ran a native root or inner fragment")
							.isTrue();
				}
			}
		}
		softly.assertAll();
	}

	@Test
	void manualInheritedGraphMatrixIncludesFreshStepControls() {
		SoftAssertions softly = new SoftAssertions();
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = strategy(dataset);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			List<BindingSet> entries = entries();
			for (int scenario = 0; scenario < 5; scenario++) {
				Projection host = nestedGraphHost(FIRST_PREDICATE, SECOND_PREDICATE, OBJECT, GRAPH, OTHER_GRAPH,
						scenario);
				for (boolean nativeMode : List.of(false, true)) {
					Projection copy = host.clone();
					checkManualShape(softly, copy, scenario, "reused native=" + nativeMode);
					QueryRoot root = new QueryRoot(copy);
					List<TupleExpr> nodes = instrument(root);
					QueryEvaluationStep step = nativeMode ? strategy.precompile(root, context)
							: strategy.genericOnlyView().precompile(root, context);
					addUnseenNodes(root, nodes);
					for (int call = 0; call < entries.size(); call++) {
						// The inconsistent fixed-lineage no-caller case is preserved in the GRAPH diagnostic packet.
						if (scenario == 0 && call == 0) {
							continue;
						}
						String label = "manual scenario=" + scenario + " native=" + nativeMode + " call=" + call;
						boolean nativeWork = evaluateAndCheck(softly, root, nodes, step, entries.get(call),
								manualExpected(scenario, call), label);
						if (!nativeMode) {
							softly.assertThat(nativeWork).as("generic-only invocation " + label).isFalse();
						} else if (scenario == 1 && call == 2) {
							softly.assertThat(nativeWork)
									.as("conflicting caller reached native execution " + label)
									.isTrue();
						}
					}
				}
			}
			for (boolean nativeMode : List.of(false, true)) {
				for (int call = 1; call < entries.size(); call++) {
					freshControl(softly, strategy, context, entries.get(call), nativeMode, 0, call);
				}
				freshControl(softly, strategy, context, entries.get(2), nativeMode, 1, 2);
			}
		}
		softly.assertAll();
	}

