				BindingSet probe = BindingFrameBindings.push(new BindingFrameBindings.Scope(),
						EmptyBindingSet.getInstance(), entries.get(2), context);
				evaluateAndCheck(softly, root, nodes, step, probe, List.of(row(SAME)),
						"borrowed conflicting graph is not a caller native=" + nativeMode);
				QueryBindingSet arbitraryParameter = new QueryBindingSet();
				arbitraryParameter.addBinding(parameter, OTHER_GRAPH);
				evaluateAndCheck(softly, root, nodes, step, arbitraryParameter, List.of(row(SAME)),
						"private-name input lacks a graph grant native=" + nativeMode);
